    '.ecc .ec-meter__track{flex:1;height:3px;border-radius:var(--r-pill);background:var(--track-empty);overflow:hidden}',
    '.ecc .ec-meter__fill{height:100%;width:33%;background:var(--progress-fill);border-radius:var(--r-pill);transition:width .28s ease}',
    '.ecc .ec-meter__count{flex:none;font-size:var(--t-fine);color:var(--ink-muted);font-variant-numeric:tabular-nums}',

    /* level 1: the question */
    '.ecc .ec-step__title{font-family:var(--font-display);font-size:var(--t-h1);font-weight:600;line-height:1.12;letter-spacing:-.01em;color:var(--ink-strong);margin:0 0 14px;text-wrap:balance}',
    '.ecc .ec-step__lede{margin:0 0 28px;max-width:34ch;font-size:var(--t-note);color:var(--ink-muted)}',

    /* level 2: the controls */
    '.ecc .ec-select{position:relative;display:block}',
    '.ecc .ec-select select{width:100%;appearance:none;-webkit-appearance:none;padding:16px 46px 16px 20px;font-size:var(--t-field);color:var(--ink-strong);background:var(--field);border:1px solid var(--field-border);border-radius:var(--r-field);cursor:pointer}',
    '.ecc .ec-select select:focus-visible{outline:none;border-color:var(--field-border-hi);box-shadow:0 0 0 3px rgba(162,77,175,.22)}',
