    '.ecc .ec-options{border:0;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:10px;background:none;border-radius:0;align-items:stretch}',
    '.ecc .ec-pill{display:flex;align-items:center;gap:8px;padding:13px 14px;min-width:0;background:var(--field);border:1px solid var(--field-border);border-radius:var(--r-pill);font-size:calc(var(--t-field) - 1px);color:var(--ink-body);cursor:pointer;line-height:1.2;transition:border-color .15s ease,color .15s ease}',
