    '.ecc .ec-pill input[type=radio]{border-radius:50%}',
    '.ecc .ec-pill input::after{content:"";width:9px;height:5px;border-left:2px solid #fff;border-bottom:2px solid #fff;transform:rotate(-45deg) scale(0);transition:transform .12s ease}',
    '.ecc .ec-pill input[type=radio]::after{width:6px;height:6px;border:0;border-radius:50%;background:#fff;transform:scale(0)}',
