    '.ecc .ec-btn--primary{background:var(--accent);color:var(--ink-invert)}',
    '.ecc .ec-btn--primary:hover{background:var(--accent-press)}',
    '.ecc .ec-btn--back{background:transparent;padding:14px 12px;color:var(--accent)}',
